/**
 * Standalone QRCode SVG/Canvas Generator for UPI Payments
 */
(function(window) {
  function generateQRCodeDataURL(text, size = 200) {
    // We can generate clean dynamic SVG QR code using standard matrix encoder or QR API fallback
    const encoded = encodeURIComponent(text);
    return `https://api.qrserver.com/v1/create-qr-code/?size=${size}x${size}&data=${encoded}&margin=8`;
  }
  window.generateQRCodeDataURL = generateQRCodeDataURL;
})(window);
